"""RoPE apply/remove/restore utilities for CompressLink NoPE pipeline."""

import torch
from torch import Tensor
from typing import Tuple


def rotate_half(x: Tensor) -> Tensor:
    x1 = x[..., : x.shape[-1] // 2]
    x2 = x[..., x.shape[-1] // 2 :]
    return torch.cat((-x2, x1), dim=-1)


def apply_rope_query_only(q: Tensor, cos: Tensor, sin: Tensor) -> Tensor:
    """Apply RoPE to query only. Same math as standard apply_rotary_pos_emb for Q."""
    return (q * cos) + (rotate_half(q) * sin)


def apply_rope_key_only(k_nope: Tensor, cos: Tensor, sin: Tensor) -> Tensor:
    """Apply RoPE to NoPE keys (forward rotation)."""
    return (k_nope * cos) + (rotate_half(k_nope) * sin)


def remove_rope(k_rope: Tensor, cos: Tensor, sin: Tensor) -> Tensor:
    """Remove RoPE from post-RoPE keys (inverse rotation)."""
    return (k_rope * cos) - (rotate_half(k_rope) * sin)


def get_rope_embeddings(
    config, positions: Tensor, device: torch.device
) -> Tuple[Tensor, Tensor]:
    """Compute cos/sin RoPE embeddings for given positions.

    Args:
        config: model config with hidden_size, num_attention_heads, rope_theta
        positions: [seq_len] or [batch, seq_len] position indices
        device: torch device

    Returns:
        cos, sin: broadcastable to [batch, 1, seq_len, head_dim]
    """
    head_dim = getattr(
        config, "head_dim", config.hidden_size // config.num_attention_heads
    )
    rope_theta = getattr(config, "rope_theta", 10000.0)

    inv_freq = 1.0 / (
        rope_theta
        ** (torch.arange(0, head_dim, 2, device=device, dtype=torch.float32) / head_dim)
    )

    if positions.dim() == 1:
        positions = positions.unsqueeze(0)

    freqs = torch.einsum("bi,j->bij", positions.float().to(device), inv_freq)
    emb = torch.cat((freqs, freqs), dim=-1)

    cos = emb.cos().unsqueeze(1)  # [batch, 1, seq_len, head_dim]
    sin = emb.sin().unsqueeze(1)

    return cos, sin

"""Boundary recomputation: fixed, query-independent restoration of chunk-boundary tokens.

Chunk-boundary tokens (first block of each chunk) lack cross-chunk attention context.
They are unconditionally recomputed regardless of query content.
"""

import torch
from torch import Tensor
from typing import List


class BoundaryRecomputer:
    def __init__(self, block_size: int = 32):
        self.block_size = block_size

    def get_boundary_indices(
        self, num_tokens: int, chunk_boundaries: List[int]
    ) -> List[int]:
        """Return all boundary token indices (first block of each chunk).

        These tokens are unconditionally recomputed, not scored.
        """
        indices = []
        for b in chunk_boundaries:
            indices.extend(range(b, min(b + self.block_size, num_tokens)))
        return sorted(set(indices))

    def restore_from_original(
        self, original_cache, decompressed_cache, boundary_indices: List[int]
    ):
        """Replace boundary tokens in decompressed cache with original values.

        MVP simulation of recomputation: the original cache (from full-context
        NoPE forward) provides the exact values that real recomputation would produce.

        Modifies decompressed_cache in-place.
        """
        if not boundary_indices:
            return

        idx = torch.tensor(boundary_indices)
        for layer_idx in range(len(decompressed_cache.key_cache)):
            decompressed_cache.key_cache[layer_idx][:, :, idx] = (
                original_cache.key_cache[layer_idx][:, :, idx]
            )
            decompressed_cache.value_cache[layer_idx][:, :, idx] = (
                original_cache.value_cache[layer_idx][:, :, idx]
            )

    def compute_boundary_budget(
        self, num_tokens: int, chunk_boundaries: List[int]
    ) -> float:
        n = len(self.get_boundary_indices(num_tokens, chunk_boundaries))
        return n / num_tokens if num_tokens > 0 else 0.0

"""Unit tests for compresslink.metrics."""

import unittest

from compresslink.metrics import compute_exact_match, compute_f1, normalize_answer


class TestNormalizeAnswer(unittest.TestCase):
    def test_lowercase(self):
        self.assertEqual(normalize_answer("Barack Obama"), "barack obama")

    def test_articles(self):
        self.assertEqual(normalize_answer("the United States of America"), "united states of america")

    def test_punctuation(self):
        self.assertEqual(normalize_answer("hello, world!"), "hello world")

    def test_whitespace(self):
        self.assertEqual(normalize_answer("  foo   bar  "), "foo bar")

    def test_combined(self):
        self.assertEqual(normalize_answer("The cat's pajamas!"), "cats pajamas")

    def test_empty(self):
        self.assertEqual(normalize_answer(""), "")


class TestExactMatch(unittest.TestCase):
    def test_exact(self):
        self.assertEqual(compute_exact_match("Barack Obama", ["Barack Obama"]), 1.0)

    def test_case_insensitive(self):
        self.assertEqual(compute_exact_match("barack obama", ["Barack Obama"]), 1.0)

    def test_article_removal(self):
        self.assertEqual(compute_exact_match("the president", ["president"]), 1.0)

    def test_no_match(self):
        self.assertEqual(compute_exact_match("George Bush", ["Barack Obama"]), 0.0)

    def test_multiple_answers(self):
        self.assertEqual(
            compute_exact_match("NYC", ["New York City", "NYC", "New York"]), 1.0
        )

    def test_multiple_no_match(self):
        self.assertEqual(
            compute_exact_match("LA", ["New York City", "NYC"]), 0.0
        )


class TestF1(unittest.TestCase):
    def test_perfect(self):
        self.assertAlmostEqual(compute_f1("Barack Obama", ["Barack Obama"]), 1.0)

    def test_partial(self):
        f1 = compute_f1("Barack Hussein Obama", ["Barack Obama"])
        self.assertGreater(f1, 0.5)
        self.assertLess(f1, 1.0)

    def test_no_overlap(self):
        self.assertAlmostEqual(compute_f1("cat", ["dog"]), 0.0)

    def test_multiple_answers(self):
        f1 = compute_f1("New York", ["New York City", "NYC"])
        self.assertGreater(f1, 0.5)

    def test_empty_prediction(self):
        self.assertAlmostEqual(compute_f1("", ["Barack Obama"]), 0.0)

    def test_subset_tokens(self):
        # "obama" is 1 of 2 answer tokens → precision=1.0, recall=0.5, F1=0.667
        f1 = compute_f1("obama", ["Barack Obama"])
        self.assertAlmostEqual(f1, 2 / 3, places=3)


if __name__ == "__main__":
    unittest.main()

